<?php
require_once dirname(__DIR__).'/app/bootstrap.php';$id=(int)($_GET['id']??0);$uid=current_user_id();$s=db()->prepare("SELECT id,name,bio,created_at,profile_visibility FROM users WHERE id=:id AND is_active=1 AND role<>'admin'");$s->execute([':id'=>$id]);$person=$s->fetch();if(!$person||(($person['profile_visibility']??'public')==='private'&&$uid!==$id)){http_response_code(404);send_not_found();}$stats=[];foreach(['reviews'=>"SELECT COUNT(*) FROM reviews WHERE user_id=:id AND status='approved'",'guides'=>"SELECT COUNT(*) FROM guides WHERE user_id=:id AND status='published'",'photos'=>"SELECT COUNT(*) FROM listing_photos WHERE user_id=:id AND status='approved'",'followers'=>"SELECT COUNT(*) FROM contributor_follows WHERE contributor_id=:id"] as $k=>$sql){$st=db()->prepare($sql);$st->execute([':id'=>$id]);$stats[$k]=(int)$st->fetchColumn();}$following=false;if($uid&&$uid!==$id){$st=db()->prepare('SELECT 1 FROM contributor_follows WHERE follower_id=:u AND contributor_id=:t');$st->execute([':u'=>$uid,':t'=>$id]);$following=(bool)$st->fetchColumn();}$score=$stats['reviews']+$stats['guides']*3+$stats['photos']*2;$badge=$score>=20?'Neighbourhood expert':($score>=8?'Local scout':'Community member');$pageTitle=$person['name'].' · Local contributor';include __DIR__.'/includes/header.php';?>
<main id="main" class="container account-page"><div class="content-panel contributor-profile"><div class="lg3-contributor-avatar large"><?= h(text_upper(text_substr($person['name'],0,1))) ?></div><span class="eyebrow">LOCAL CONTRIBUTOR</span><h1><?= h($person['name']) ?></h1><span class="status-pill status-approved"><?= h($badge) ?></span><p><?= h($person['bio']?:'A member of the Local Guide community.') ?></p><div class="stats-grid"><article class="stat-card"><span>Helpful reviews</span><strong><?= $stats['reviews'] ?></strong></article><article class="stat-card"><span>Published guides</span><strong><?= $stats['guides'] ?></strong></article><article class="stat-card"><span>Approved photos</span><strong><?= $stats['photos'] ?></strong></article><article class="stat-card"><span>Followers</span><strong><?= $stats['followers'] ?></strong></article></div><?php if($uid&&$uid!==$id): ?><form method="post" action="community.php#contributors"><?= csrf_field() ?><input type="hidden" name="action" value="follow"><input type="hidden" name="contributor_id" value="<?= $id ?>"><button class="button button-primary"><?= $following?'Unfollow contributor':'Follow contributor' ?></button></form><?php elseif(!$uid): ?><a class="button button-primary" href="auth.php">Sign in to follow</a><?php endif; ?></div><a class="button button-outline" href="community.php">Back to community</a></main><?php include __DIR__.'/includes/footer.php';?>
